import{_ as e,H as i,f as t,i as l}from"./chunks/framework.DIv0Dgmf.js";const u=JSON.parse('{"title":"第十章：Git 操作辅助","description":"学会让 Claude 辅助 Git 操作","frontmatter":{"title":"第十章：Git 操作辅助","description":"学会让 Claude 辅助 Git 操作"},"headers":[],"relativePath":"guide/3-practical-workflows/10-git-operations.md","filePath":"guide/3-practical-workflows/10-git-operations.md"}'),s={name:"guide/3-practical-workflows/10-git-operations.md"};function o(r,a,d,c,n,p){return i(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="第十章-git-操作辅助" tabindex="-1">第十章：Git 操作辅助 <a class="header-anchor" href="#第十章-git-操作辅助" aria-label="Permalink to &quot;第十章：Git 操作辅助&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你会让 Claude 帮你处理 Git 操作。</p></div><h2 id="git-基础回顾" tabindex="-1">Git 基础回顾 <a class="header-anchor" href="#git-基础回顾" aria-label="Permalink to &quot;Git 基础回顾&quot;">​</a></h2><p>Git 是版本控制工具，常用命令：</p><ul><li><code>git add</code> - 暂存文件</li><li><code>git commit</code> - 提交</li><li><code>git push</code> - 推送到远程</li><li><code>git pull</code> - 拉取更新</li><li><code>git branch</code> - 管理分支</li></ul><h2 id="让-claude-帮你写-commit-message" tabindex="-1">让 Claude 帮你写 Commit Message <a class="header-anchor" href="#让-claude-帮你写-commit-message" aria-label="Permalink to &quot;让 Claude 帮你写 Commit Message&quot;">​</a></h2><h3 id="查看修改" tabindex="-1">查看修改 <a class="header-anchor" href="#查看修改" aria-label="Permalink to &quot;查看修改&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我看看这些修改</span></span></code></pre></div><h3 id="写-commit-message" tabindex="-1">写 Commit Message <a class="header-anchor" href="#写-commit-message" aria-label="Permalink to &quot;写 Commit Message&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写一个 commit message</span></span></code></pre></div><p>Claude 会根据你的修改内容，写一个清晰的 commit message。</p><h2 id="处理-merge-冲突" tabindex="-1">处理 Merge 冲突 <a class="header-anchor" href="#处理-merge-冲突" aria-label="Permalink to &quot;处理 Merge 冲突&quot;">​</a></h2><h3 id="遇到冲突时" tabindex="-1">遇到冲突时 <a class="header-anchor" href="#遇到冲突时" aria-label="Permalink to &quot;遇到冲突时&quot;">​</a></h3><p>把冲突信息粘贴给 Claude：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这个冲突怎么解决？</span></span></code></pre></div><p>Claude 会解释冲突是什么，以及如何合并。</p><h2 id="写-pr-描述" tabindex="-1">写 PR 描述 <a class="header-anchor" href="#写-pr-描述" aria-label="Permalink to &quot;写 PR 描述&quot;">​</a></h2><p>在 GitHub 上创建 Pull Request 时：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>帮我写一个 PR 描述，说明这个 PR 做了什么</span></span></code></pre></div><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>知道 Git 是什么（不知道也没关系）。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: merge 冲突太复杂？</strong></p><p>A: 让 Claude 先解释冲突是什么，再决定怎么合并。</p><p><strong>Q: 误操作了？</strong></p><p>A: <code>git reflog</code> 可以找回之前的版本。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><ol><li>修改文件，用 Claude 帮你写 commit message</li><li>制造一个 merge 冲突，让 Claude 帮你分析</li></ol><h2 id="继续学习" tabindex="-1">继续学习 <a class="header-anchor" href="#继续学习" aria-label="Permalink to &quot;继续学习&quot;">​</a></h2><p>恭喜你完成了入门篇和基础篇！</p><p>现在你可以：</p><ul><li>安装和配置 Claude Code</li><li>读懂代码库</li><li>编写和修改代码</li><li>调试问题</li><li>代码审查</li><li>Git 操作</li></ul><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>查看 <a href="/claude-code-guide/guide/3-practical-workflows/12-realistic-workflow.html">继续学习之路</a> 了解进阶话题。</p>',34)])])}const m=e(s,[["render",o]]);export{u as __pageData,m as default};
